from datetime import datetime, timedelta
from typing import Tuple, Optional
import re

def parse_date_flexible(
    date_string: str,
    base_date: Optional[str] = None,
    output_format: str = 'iso'
) -> Tuple[bool, str, str]:
    """
    灵活解析各种日期格式。
    """
    if not date_string:
        return False, '', 'invalid'

    date_string = date_string.strip().lower()

    # 确定基准日期
    if base_date:
        try:
            now = datetime.fromisoformat(base_date.replace('Z', '+00:00'))
        except:
            now = datetime.now()
    else:
        now = datetime.now()

    result = None
    detected_format = 'unknown'

    # 自然语言处理
    if date_string in ['今天', 'today']:
        result = now
        detected_format = 'natural_today'
    elif date_string in ['昨天', 'yesterday']:
        result = now - timedelta(days=1)
        detected_format = 'natural_yesterday'
    elif date_string in ['明天', 'tomorrow']:
        result = now + timedelta(days=1)
        detected_format = 'natural_tomorrow'
    elif re.match(r'(\d+)天前', date_string):
        days = int(re.search(r'(\d+)', date_string).group(1))
        result = now - timedelta(days=days)
        detected_format = 'natural_relative_past'
    elif re.match(r'(\d+)天后', date_string):
        days = int(re.search(r'(\d+)', date_string).group(1))
        result = now + timedelta(days=days)
        detected_format = 'natural_relative_future'

    # 标准格式解析
    if result is None:
        formats = [
            ('%Y-%m-%d', 'iso_date'),
            ('%Y/%m/%d', 'slash_date'),
            ('%d/%m/%Y', 'eu_date'),
            ('%m/%d/%Y', 'us_date'),
            ('%d-%m-%Y', 'eu_dash_date'),
            ('%Y%m%d', 'compact_date'),
            ('%Y-%m-%d %H:%M:%S', 'iso_datetime'),
        ]

        for fmt, fmt_name in formats:
            try:
                result = datetime.strptime(date_string, fmt)
                detected_format = fmt_name
                break
            except ValueError:
                continue

    if result is None:
        return False, '', 'invalid'

    # 格式化输出
    if output_format == 'iso':
        output = result.strftime('%Y-%m-%d')
    elif output_format == 'timestamp':
        output = str(int(result.timestamp()))
    elif output_format == 'datetime':
        output = result.isoformat()
    else:
        output = result.strftime('%Y-%m-%d')

    return True, output, detected_format
